ValidationRule.errorConditionFormula:
NOT(ISNEW()) &&
ISCHANGED(sked_Status__c) &&
(
     (ISPICKVAL(PRIORVALUE(sked_Status__c), "Draft") &&
        ( NOT(ISPICKVAL(sked_Status__c, "System Generated")) && NOT(ISPICKVAL(sked_Status__c, "Tentative"))
         && NOT(ISPICKVAL(sked_Status__c, "Cancel")) && NOT(ISPICKVAL(sked_Status__c, "Hold"))
        ) 
     )||
    (ISPICKVAL(PRIORVALUE(sked_Status__c), "Hold") &&
       ( NOT(ISPICKVAL(sked_Status__c, "Draft")) && NOT(ISPICKVAL(sked_Status__c, "Tentative"))
          && NOT(ISPICKVAL(sked_Status__c, "Cancel")) && NOT(ISPICKVAL(sked_Status__c, "Confirmed"))
       ) 
     )|| 
     (ISPICKVAL(PRIORVALUE(sked_Status__c), "System Generated") &&
       (NOT(ISPICKVAL(sked_Status__c, "Tentative"))
          && NOT(ISPICKVAL(sked_Status__c, "Cancel")) && NOT(ISPICKVAL(sked_Status__c, "Confirmed"))
       ) 
     )|| 
     (ISPICKVAL(PRIORVALUE(sked_Status__c), "Confirmed") &&
       ( NOT(ISPICKVAL(sked_Status__c, "Cancel")) && NOT(ISPICKVAL(sked_Status__c, "Complete")) && NOT(ISPICKVAL(sked_Status__c, "Confirmed"))
       ) 
     )|| 
     (ISPICKVAL(PRIORVALUE(sked_Status__c), "Complete") &&
       ( NOT(ISPICKVAL(sked_Status__c, "Cancel"))
       ) 
     )|| 
     (ISPICKVAL(PRIORVALUE(sked_Status__c), "Cancel") &&
       ( NOT(ISPICKVAL(sked_Status__c, "Cancel"))
       ) 
     )|| 
     (
     (ISPICKVAL(PRIORVALUE(sked_Status__c), "Tentative")  && 
      NOT(ISPICKVAL(sked_Status__c, "Cancel")) && NOT(ISPICKVAL(sked_Status__c, "Confirmed"))
       ) 
     )

)
&&
$Profile.Name <> 'System Administrator' &&
$Profile.Name <> 'Global Admin'
